const process = require('process');

function fizzBuzz(n) {
  const result = [];
  for (let i = 1; i <= n; i++) {
    if (i % 3 === 0 && i % 5 === 0) {
      result.push('FizzBuzz');
    } else if (i % 3 === 0) {
      result.push('Fizz');
    } else if (i % 5 === 0) {
      result.push('Buzz');
    } else {
      result.push(i.toString());
    }
  }
  return result;
}

const N = parseInt(process.argv[2], 10);
console.log(JSON.stringify(fizzBuzz(N)));

const fs = require('fs');

function parseCSV(filePath) {
  return new Promise((resolve, reject) => {
    fs.readFile(filePath, 'utf8', (err, data) => {
      if (err) reject(err);
      const lines = data.split('\n').filter(line => line.trim() !== '');
      const header = lines.shift().split(',');
      const parsedData = lines.map(row => {
        const values = row.split(',').map(value => value.trim());
        return header.reduce((obj, key, index) => ({ ...obj, [key]: values[index] }), {});
      });
      resolve(parsedData);
    });
  });
}

if (process.argv.length !== 3) {
  console.error('Usage: node convert.js <csvFilePath>');
  process.exit(1);
}

parseCSV(process.argv[2]).then(data => {
  console.log(JSON.stringify(data, null, 2));
}).catch(err => {
  console.error('Error parsing CSV:', err);
});

